// @ts-nocheck
import { Util } from '../Util';
import { ValueBinder } from './value/ValueBinder';

/**
 *  '@bind' decorator will convert a property into an invalidated setter and getter and
 *  create a local member of the property.
 */
export function bind<T>(debug?: boolean): (target: object, propertyKey: string) => void {
    return function (target: object, propertyKey: string): void {
        const localPropKey: string = BindingModel.LOCAL_MODEL_VALUE_IDENTIFIER + propertyKey;
        Object.defineProperty(target, localPropKey, {
            configurable: true,
            writable: true,
        });
        // eslint-disable-next-line
        const getter = function (): void {
            return this[localPropKey];
        };
        // eslint-disable-next-line
        const setter = function (newVal: T): void {
            this[localPropKey] = newVal;
            (this as BindingModel).invalidate(localPropKey);
            // eslint-disable-next-line
            debug ? console.log(localPropKey, 'set to', newVal) : null;
        };
        Object.defineProperty(target, propertyKey, {
            get: getter,
            set: setter
        });
    };
}

/**
 *  '@bindPassive' decorator will convert a property into a setter and getter and
 *  create a local member of the property, will not invalidate on set.
 */
export function bindPassive<T>(debug?: boolean): (target: object, propertyKey: string) => void {
    return function (target: object, propertyKey: string): void {
        const localPropKey: string = BindingModel.LOCAL_MODEL_VALUE_IDENTIFIER + propertyKey;
        Object.defineProperty(target, localPropKey, {
            configurable: true,
            writable: true,
        });
        // eslint-disable-next-line
        const getter = function (): void {
            return this[localPropKey];
        };
        // eslint-disable-next-line
        const setter = function (newVal: T): void {
            this[localPropKey] = newVal;
            // eslint-disable-next-line
            debug ? console.log(localPropKey, 'set to', newVal) : null;
        };
        Object.defineProperty(target, propertyKey, {
            get: getter,
            set: setter
        });
    };
}

/*
 *  bindTag will accept '() => gamemodel.myValue' or legacy premade strings 'gamemodel.MY_VALUE'
 */
// eslint-disable-next-line
export type bindTag = string | (() => any);

export abstract class BindingModel {
    /*
    *  This is the member identifier you are using in your model to specify
    *  the local value, '_' is used by default.
    */
    public static LOCAL_MODEL_VALUE_IDENTIFIER: string = '_';

    private _binders: ValueBinder[] = [];

    /*
     * Creates each Value binder in the _binders vector that is used to later update values
     * Note the 1 to Many relationship
     * @param value The static const the binder is attached too (reflects the variable in the super model);
     * @param ... List of Bindable properties to bind the value to
     */
    // eslint-disable-next-line
    public bindToValue(scope: any, remoteModelValue: bindTag, localClassValue: bindTag, invalidate: boolean = false): ValueBinder {

        const propertyName: string = typeof remoteModelValue === 'string' ? remoteModelValue : Util.getVariableName(remoteModelValue, true);
        const functionName: string = typeof localClassValue === 'string' ? localClassValue : Util.getVariableName(localClassValue);

        if (!this._binders) {
            return new ValueBinder('', {}, '');
        }

        this._binders.forEach(($valueBinder: ValueBinder) => {
            if ($valueBinder.scope === scope && $valueBinder.property === functionName && $valueBinder.value === propertyName) {
                this._binders.splice(this._binders.indexOf($valueBinder), 1);
            }
        });

        const valueBinderID = new ValueBinder(propertyName, scope, functionName);
        this._binders.push(valueBinderID);

        if (invalidate === true) {
            scope[functionName](this.property(propertyName));
        }

        return valueBinderID;
    }

    public get binders(): ValueBinder[] {
        return this._binders;
    }

    /*
     * Invalidates the given values and updates views as appropriate
     * @param ... list of values
     */
    public invalidate(...args: any[]): void {
        args.forEach(($value) => {
            const propertyName: string = typeof $value === 'string' ? $value : Util.getVariableName($value, true);
            this.updateValueBinder(propertyName);
        });
    }

    /*
     * Overriden in the parent and used to get the property or variables
     */
    public property<T>(propertyName: string): T {
        // eslint-disable-next-line
        return (this as any)[propertyName];
    }

    public setProperty<T>(propertyName: string, newValue: T): void {
        // eslint-disable-next-line
        (this as any)[propertyName] = newValue;
    }

    public removeBinding(valueBinder: ValueBinder): void {
        this._binders.forEach(($valueBinder: ValueBinder) => {
            if ($valueBinder === valueBinder) {
                this._binders.splice(this._binders.indexOf($valueBinder), 1);
            }
        });
    }

    public removeBindingsOf<Context>(scope: Context, localClassValue: bindTag = ''): void {
        const functionName: string = typeof localClassValue === 'string' ? localClassValue : Util.getVariableName(localClassValue);
        this._binders.forEach(($valueBinder: ValueBinder) => {
            if ($valueBinder.scope === scope) {
                if ($valueBinder.property === functionName || functionName === '') {
                    this._binders.splice(this._binders.indexOf($valueBinder), 1);
                }
            }
        });
    }

    /*
    * Runs through the binders array, matching a specific value string, then updates those values with the property of that value
    * @param value value for the variable to update
    */
    protected updateValueBinder(value: string): void {
        if (!this._binders) {
            return;
        }
        this._binders.forEach(($valueBinder: ValueBinder) => {
            if ($valueBinder.value === value && $valueBinder.scope) {
                $valueBinder.scope[$valueBinder.property](this.property(value));
            }
        });
    }

    /*
     *  setLocal allows access to an '@bind' decoratored property , without calling invalidation.
     */
    protected setLocal<T>(propertyName: bindTag, newVal: T): void {
        const localVarName = typeof propertyName === 'string' ? propertyName : Util.getVariableName(propertyName, true);
        // eslint-disable-next-line
        (this as any)[localVarName] = newVal;
    }

}
